#[must_use]
pub fn session_log_dir() -> PathBuf {
    std::env::current_dir()
        .unwrap_or_else(|_| PathBuf::from("."))
        .join(".yach")
        .join("sessions")
}

#[must_use]
pub fn session_log_path(session_id: &str) -> PathBuf {
    session_log_dir().join(format!("{session_id}.jsonl"))
}

#[must_use]
pub fn fresh_session_id() -> String {
    let timestamp_nanos = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map_or(0, |duration| duration.as_nanos());
    format!("session-{}-{timestamp_nanos}", std::process::id())
}

#[must_use]
pub fn session_id_from_log_path(path: &Path) -> Option<String> {
    let extension = path.extension()?.to_str()?;
    if extension != "jsonl" {
        return None;
    }
    let stem = path.file_stem()?.to_str()?;
    if stem.is_empty() {
        return None;
    }
    Some(stem.to_owned())
}

#[must_use]
pub fn latest_native_session_log_path() -> Option<PathBuf> {
    latest_native_session_log_path_in(&session_log_dir())
}

#[must_use]
pub fn latest_native_session_log_path_in(session_dir: &Path) -> Option<PathBuf> {
    std::fs::read_dir(session_dir)
        .ok()?
        .filter_map(Result::ok)
        .map(|entry| entry.path())
        .filter(|path| session_id_from_log_path(path).is_some())
        .filter_map(|path| {
            let modified = std::fs::metadata(&path).ok()?.modified().ok()?;
            Some((modified, path))
        })
        .max_by_key(|(modified, _)| *modified)
        .map(|(_, path)| path)
}

/// Run the native backend event loop.
pub async fn run_native_loop(
    rx: mpsc::UnboundedReceiver<ClientEvent>,
    tx: mpsc::UnboundedSender<BackendEvent>,
    config: RunnerConfig,
) {
    run_native_loop_with_requester_factory(rx, tx, config, |provider| RigProviderRequester {
        adapter: provider.adapter.clone(),
        approved_tools: provider_approved_tools(),
    })
    .await;
}

#[cfg(test)]
async fn run_native_loop_with_provider_requester<Requester>(
    rx: mpsc::UnboundedReceiver<ClientEvent>,
    tx: mpsc::UnboundedSender<BackendEvent>,
    config: RunnerConfig,
    requester: Requester,
) where
    Requester: ProviderRequester + Send + 'static,
{
    let mut requester = Some(requester);
    run_native_loop_with_requester_factory(rx, tx, config, move |_| {
        let Some(requester) = requester.take() else {
            unreachable!("test provider requester can only be used once");
        };
        requester
    })
    .await;
}

async fn run_native_loop_with_requester_factory<MakeRequester, Requester>(
    mut rx: mpsc::UnboundedReceiver<ClientEvent>,
    tx: mpsc::UnboundedSender<BackendEvent>,
    config: RunnerConfig,
    mut make_requester: MakeRequester,
) where
    MakeRequester: FnMut(&ProviderConfig) -> Requester,
    Requester: ProviderRequester + Send + 'static,
{
    let RunnerConfig {
        mut session_path,
        project_root,
        mut provider,
        provider_setup_error,
        extension_package_roots,
        extension_package_root_loader,
        startup_trace,
        catalog_refresh,
        mut model_discovery,
        provider_connections,
    } = config;
    // The main loop below is purely event-driven (`while let Some(event) =
    // rx.recv().await`, no periodic tick/`select!` arm) — a `try_recv`
    // polled from inside it would only ever run when a `ClientEvent`
    // happens to arrive, so an idle session could sit on a ready refresh
    // outcome indefinitely. Instead, forward it via one detached OS
    // thread that blocks on the one message this receiver ever carries
    // and relays it into the same event channel both TUI and headless
    // read from — a single seam for both. A plain `std::thread::spawn`
    // rather than `tokio::task::spawn_blocking`: dropping a Tokio runtime
    // waits for outstanding blocking-pool work, and this can block for as
    // long as the CLI's fetch timeout: a detached thread has no such
    // coupling and dies with the process.
    if let Some(catalog_refresh) = catalog_refresh {
        let tx = tx.clone();
        std::thread::spawn(move || {
            if let Ok(message) = catalog_refresh.recv() {
                let _ = tx.send(BackendEvent::Server(ServerEvent::StatusUpdated { message }));
            }
        });
    }
    let mut current_session_id =
        session_id_from_log_path(&session_path).unwrap_or_else(|| String::from("default"));
    let mut store = JsonlSessionStore::new(session_path.clone());
    let provider_project_context = effective_runner_project_context(project_root.as_deref());
    let edit_root = local_edit_root(project_root.clone());
    let mut edit_access = EditAccess::default();
    send_native_initial_state(
        &tx,
        &current_session_id,
        &session_path,
        provider.as_ref(),
        provider_setup_error.as_deref(),
    );
    for warning in crate::SensitivePathPolicy::load_for_project(project_root.as_deref()).1 {
        let message = match warning {
            crate::SensitivePathConfigWarning::InvalidConfig { path, .. } => {
                format!(
                    "sensitive_file_config: invalid config at {path}; built-in deny defaults remain in force"
                )
            }
            crate::SensitivePathConfigWarning::InvalidPattern { pattern } => {
                format!(
                    "sensitive_file_config: invalid pattern {pattern:?}; built-in deny defaults remain in force"
                )
            }
        };
        let _ = tx.send(BackendEvent::Server(ServerEvent::StatusUpdated { message }));
    }
    let mut session_log = load_native_session_log_for_runner(&tx, &store).await;
    // Authoritative opaque Responses replay survives prompt task cancellation
    // and is shared by ordinary turns and manual compaction.
    let native_replay: crate::responses_replay::NativeReplayStore = Arc::new(Mutex::new(
        crate::responses_replay::NativeReplayStoreState::default(),
    ));
    // Push stats (and therefore the context meter) at startup; previously
    // the meter stayed empty until the first turn finished.
    send_native_session_stats_from_log(
        &tx,
        &session_log,
        context_budget(provider.as_ref(), project_root.as_deref()),
    );
    let mut turn_index = session_log.next_turn_index();
    let mut local_edit_index = turn_index;
    let mut active_provider_turn: Option<ActiveProviderTurn> = None;
    let mut extension_manifest_scan_scheduled = false;
    let extension_manifest_scan_state = Arc::new(AsyncMutex::new(None));
    let extension_activation_state = Arc::new(AsyncMutex::new(
        crate::ExtensionActivationSnapshot::default(),
    ));
    let mut discovery_in_flight = false;
    let (discovery_update_tx, mut discovery_update_rx) = mpsc::unbounded_channel();
    let mut connection_flow = ProviderConnectionFlow::new(provider.as_ref().map(|provider| {
        crate::ActiveModelTarget {
            connection_id: provider
                .connection_id
                .clone()
                .unwrap_or_else(ConnectionId::environment),
            model: provider.model.clone(),
        }
    }));
    let mut advertised_catalog: Arc<[CatalogModelEntry]> = Arc::from([]);
    let (connection_update_tx, mut connection_update_rx) = mpsc::unbounded_channel();
    let (connection_model_refresh_tx, mut connection_model_refresh_rx) = mpsc::unbounded_channel();
    let (activation_update_tx, mut activation_update_rx) = mpsc::unbounded_channel();
    let mut activation_generation = 0_u64;
    let mut activation_in_flight: Option<InFlightModelActivation> = None;
    let mut connection_model_refresh_generation = 0_u64;
    let mut connection_model_refresh_in_flight = None;
    let mut connection_model_refresh_pending = false;
    let mut first_render_completed = false;

    loop {
        let event = tokio::select! {
            event = rx.recv() => event.map(NativeLoopEvent::Client),
            outcome = discovery_update_rx.recv(), if discovery_in_flight => {
                outcome.map(NativeLoopEvent::Discovery)
            }
            update = connection_update_rx.recv() => update.map(NativeLoopEvent::Connection),
            update = connection_model_refresh_rx.recv() => update.map(|(generation, outcome)| {
                NativeLoopEvent::ConnectionModelRefresh {
                    generation,
                    outcome,
                }
            }),
            update = activation_update_rx.recv() => {
                update.map(|(generation, target, outcome)| NativeLoopEvent::Activation {
                    generation,
                    target,
                    outcome,
                })
            },
        };
        let Some(event) = event else {
            if rx.is_closed() {
                break;
            }
            discovery_in_flight = false;
            continue;
        };
        let event = match event {
            NativeLoopEvent::Discovery(outcome) => {
                discovery_in_flight = false;
                collect_finished_provider_turn(&tx, &mut active_provider_turn, &mut session_log)
                    .await;
                match outcome {
                    ModelDiscoveryOutcome::Available(entries)
                    | ModelDiscoveryOutcome::AvailableWithWarnings {
                        entries,
                        warnings: _,
                    } => {
                        if let Some(provider) = provider.as_mut() {
                            provider.catalog_models = entries.into();
                        }
                        let _ = tx.send(BackendEvent::Server(ServerEvent::StatusUpdated {
                            message: String::from("model discovery loaded; select a model"),
                        }));
                    }
                    ModelDiscoveryOutcome::Superseded => {}
                    ModelDiscoveryOutcome::Failed { message } => {
                        let _ =
                            tx.send(BackendEvent::Server(ServerEvent::StatusUpdated { message }));
                    }
                }
                send_native_models(&tx, provider.as_ref(), provider_setup_error.as_deref());
                continue;
            }
            NativeLoopEvent::Activation {
                generation,
                target,
                outcome,
            } => {
                if activation_in_flight
                    .as_ref()
                    .map(|activation| activation.generation)
                    != Some(generation)
                {
                    continue;
                }
                activation_in_flight = None;
                if generation != activation_generation {
                    continue;
                }
                if active_provider_turn
                    .as_ref()
                    .is_some_and(|active| !active.handle.is_finished())
                {
                    send_model_change_failed(
                        &tx,
                        target,
                        String::from("model change unavailable while a prompt is in progress"),
                    );
                    continue;
                }
                match outcome {
                    ProviderActivationOutcome::Activated(candidate) => {
                        let model = candidate.model.clone();
                        let connection_id = candidate
                            .connection_id
                            .as_ref()
                            .map(|id| id.as_str().to_owned());
                        let provider_label = candidate.provider_label().to_owned();
                        connection_flow.set_active_target(candidate.connection_id.as_ref().map(
                            |id| crate::ActiveModelTarget {
                                connection_id: id.clone(),
                                model: model.clone(),
                            },
                        ));
                        if let (Some(runtime), Some(target)) = (
                            provider_connections.as_ref(),
                            connection_flow.active_target().cloned(),
                        ) {
                            runtime.remember_selection(target);
                        }
                        provider = Some(candidate);
                        let _ = tx.send(BackendEvent::Server(ServerEvent::StatusUpdated {
                            message: format!("model changed to {model}"),
                        }));
                        let _ = tx.send(BackendEvent::Server(ServerEvent::ModelChanged(
                            ModelChangeTarget {
                                model,
                                connection_id,
                                provider: Some(provider_label),
                                request_id: target.request_id,
                            },
                        )));
                    }
                    ProviderActivationOutcome::Failed(_) => {
                        send_model_change_failed(
                            &tx,
                            target,
                            String::from("model activation failed"),
                        );
                    }
                }
                continue;
            }
            NativeLoopEvent::ConnectionModelRefresh {
                generation,
                outcome,
            } => {
                if connection_model_refresh_in_flight != Some(generation) {
                    continue;
                }
                connection_model_refresh_in_flight = None;
                if generation == connection_model_refresh_generation {
                    match outcome {
                        ModelDiscoveryOutcome::Available(entries) => {
                            publish_connection_catalog(
                                &tx,
                                provider.as_ref(),
                                provider_setup_error.as_deref(),
                                &mut advertised_catalog,
                                entries,
                                Vec::new(),
                            );
                        }
                        ModelDiscoveryOutcome::AvailableWithWarnings { entries, warnings } => {
                            publish_connection_catalog(
                                &tx,
                                provider.as_ref(),
                                provider_setup_error.as_deref(),
                                &mut advertised_catalog,
                                entries,
                                warnings,
                            );
                        }
                        ModelDiscoveryOutcome::Superseded => {}
                        ModelDiscoveryOutcome::Failed { .. } => {
                            let _ = tx.send(BackendEvent::Server(ServerEvent::StatusUpdated {
                                message: String::from("provider model refresh failed"),
                            }));
                        }
                    }
                }
                if connection_model_refresh_pending {
                    connection_model_refresh_pending = false;
                    if let Some(runtime) = provider_connections.as_ref() {
                        start_connection_model_refresh(
                            runtime,
                            &connection_flow,
                            provider.as_ref(),
                            connection_model_refresh_generation,
                            &mut connection_model_refresh_in_flight,
                            &connection_model_refresh_tx,
                        );
                    }
                }
                continue;
            }
            NativeLoopEvent::Connection(update) => {
                collect_finished_provider_turn(&tx, &mut active_provider_turn, &mut session_log)
                    .await;
                let mut mutation_succeeded = false;
                let effects = match update {
                    ConnectionRuntimeUpdate::List {
                        generation,
                        outcome,
                    } => connection_flow.complete_list(generation, outcome),
                    ConnectionRuntimeUpdate::Mutation(outcome) => {
                        mutation_succeeded = matches!(
                            outcome,
                            ConnectionMutationOutcome::Succeeded
                                | ConnectionMutationOutcome::Renamed { .. }
                        );
                        if let ConnectionMutationOutcome::Renamed { id, display } = &outcome {
                            apply_active_connection_rename(&mut provider, id, display.as_ref());
                        }
                        connection_flow.complete_mutation(&outcome)
                    }
                    ConnectionRuntimeUpdate::Replacement(outcome) => match outcome {
                        ConnectionReplacementOutcome::Succeeded { candidate } => {
                            if let Some(candidate) = candidate.filter(|candidate| {
                                provider.as_ref().is_some_and(|active| {
                                    candidate.connection_id == active.connection_id
                                })
                            }) {
                                provider = Some(candidate);
                            }
                            mutation_succeeded = true;
                            let outcome = ConnectionMutationOutcome::Succeeded;
                            connection_flow.complete_mutation(&outcome)
                        }
                        ConnectionReplacementOutcome::Failed(failure) => {
                            let outcome = ConnectionMutationOutcome::Failed(failure);
                            connection_flow.complete_mutation(&outcome)
                        }
                    },
                };
                if mutation_succeeded {
                    clear_connection_catalog(
                        &tx,
                        provider.as_ref(),
                        provider_setup_error.as_deref(),
                        &mut advertised_catalog,
                    );
                }
                apply_connection_flow_effects(
                    effects,
                    ConnectionFlowEffectContext {
                        runtime: provider_connections.as_ref(),
                        tx: &tx,
                        flow: &connection_flow,
                        provider: provider.as_ref(),
                        connection_updates: &connection_update_tx,
                        model_refresh_updates: &connection_model_refresh_tx,
                        model_refresh_generation: &mut connection_model_refresh_generation,
                        model_refresh_in_flight: &mut connection_model_refresh_in_flight,
                        model_refresh_pending: &mut connection_model_refresh_pending,
                        activation_generation: &mut activation_generation,
                        activation_in_flight: &mut activation_in_flight,
                    },
                );
                continue;
            }
            NativeLoopEvent::Client(event) => event,
        };
        collect_finished_provider_turn(&tx, &mut active_provider_turn, &mut session_log).await;
        match event {
            ClientEvent::Initialize(_) => {
                send_native_initial_state(
                    &tx,
                    &current_session_id,
                    &session_path,
                    provider.as_ref(),
                    provider_setup_error.as_deref(),
                );
            }
            ClientEvent::FirstRenderCompleted => {
                first_render_completed = true;
                let extension_package_roots = extension_package_roots_for_scan(
                    &extension_package_roots,
                    extension_package_root_loader.as_ref(),
                );
                schedule_extension_manifest_scan(
                    &tx,
                    extension_package_roots,
                    extension_manifest_scan_state.clone(),
                    extension_activation_state.clone(),
                    startup_trace.clone(),
                    &mut extension_manifest_scan_scheduled,
                );
                if let Some(runtime) = provider_connections.as_ref()
                    && let Some(target) = runtime.remembered_selection()
                {
                    let already_active = provider.as_ref().is_some_and(|configured| {
                        configured.connection_id.as_ref() == Some(&target.connection_id)
                            && configured.model == target.model
                    });
                    if !already_active {
                        activation_generation = activation_generation.wrapping_add(1);
                        let generation = activation_generation;
                        let activation_update_tx = activation_update_tx.clone();
                        let requested = ModelChangeTarget {
                            model: target.model.clone(),
                            connection_id: Some(target.connection_id.as_str().to_owned()),
                            provider: None,
                            request_id: None,
                        };
                        activation_in_flight = Some(InFlightModelActivation {
                            generation,
                            target: requested.clone(),
                        });
                        let future =
                            runtime.activate(target.connection_id.clone(), target.model.clone());
                        tokio::spawn(async move {
                            let _ =
                                activation_update_tx.send((generation, requested, future.await));
                        });
                    }
                }
            }
            ClientEvent::AvailableModelsRequested => {
                if first_render_completed && let Some(runtime) = provider_connections.as_ref() {
                    if let Some(cached) = runtime.cached_models() {
                        advertised_catalog = cached;
                    }
                    send_native_models_with_catalog(
                        &tx,
                        provider.as_ref(),
                        provider_setup_error.as_deref(),
                        Some(&advertised_catalog),
                    );
                    request_connection_model_refresh(
                        runtime,
                        &connection_flow,
                        provider.as_ref(),
                        &mut connection_model_refresh_generation,
                        &mut connection_model_refresh_in_flight,
                        &mut connection_model_refresh_pending,
                        &connection_model_refresh_tx,
                    );
                } else {
                    if let Some(discovery) = model_discovery.take() {
                        let discovery_update_tx = discovery_update_tx.clone();
                        tokio::spawn(async move {
                            let _ = discovery_update_tx.send(discovery.await);
                        });
                        discovery_in_flight = true;
                    }
                    send_native_models(&tx, provider.as_ref(), provider_setup_error.as_deref());
                }
            }
            ClientEvent::PromptCancelled { .. } => {
                if let Some(active) = active_provider_turn.take() {
                    let session_id = SessionId(current_session_id.clone());
                    cancel_active_provider_turn(&tx, &store, &session_id, active, &mut session_log)
                        .await;
                }
            }
            ClientEvent::RecentSessionsRequested => send_native_recent_sessions(&tx, &session_path),
            ClientEvent::SessionMessagesRequested => {
                send_native_session_messages_from_log(&tx, &session_log);
            }
            ClientEvent::SessionStatsRequested => {
                send_native_session_stats_from_log(
                    &tx,
                    &session_log,
                    context_budget(provider.as_ref(), project_root.as_deref()),
                );
            }
            ClientEvent::CompactionRequested { instructions, .. } => {
                if active_provider_turn
                    .as_ref()
                    .is_some_and(|active| !active.handle.is_finished())
                {
                    let _ = tx.send(BackendEvent::Server(ServerEvent::StatusUpdated {
                        message: String::from(
                            "compaction unavailable while a prompt is in progress",
                        ),
                    }));
                    continue;
                }
                let Some(provider) = provider.clone() else {
                    let _ = tx.send(BackendEvent::Server(ServerEvent::StatusUpdated {
                        message: String::from("compaction requires a configured provider"),
                    }));
                    continue;
                };
                let compaction_config =
                    crate::CompactionConfig::load_for_project(project_root.as_deref());
                if crate::select_compaction_cut(&session_log, compaction_config.keep_recent_tokens)
                    .is_none()
                {
                    let _ = tx.send(BackendEvent::Server(ServerEvent::StatusUpdated {
                        message: String::from("nothing to compact yet"),
                    }));
                    continue;
                }
                let compaction_turn = TurnId(format!("turn-{turn_index}"));
                turn_index = turn_index.saturating_add(1);
                local_edit_index = local_edit_index.max(turn_index);
                let mut requester = make_requester(&provider);
                let model = ProviderModel {
                    provider: provider.provider_label().to_owned(),
                    model: provider.model.clone(),
                };
                let tokens_before = crate::estimate_current_context_tokens(&session_log);
                let mut pending_events = Vec::new();
                let manual_static_context = effective_static_context(
                    provider_project_context.as_ref(),
                    extension_static_context_files_from_scan_state(&extension_manifest_scan_state)
                        .await,
                );
                let manual_messages = provider_messages_from_log_with_static_context(
                    &session_log,
                    &compaction_turn,
                    &manual_static_context,
                );
                let native_request = assemble_native_replay_request(
                    &native_replay,
                    &session_log,
                    &SessionId(current_session_id.clone()),
                    &model,
                    &provider,
                    &manual_messages,
                    &compaction_turn,
                );
                let mut manual_replay = native_replay_snapshot(&native_replay);
                let result = run_compaction(
                    &mut requester,
                    CompactionRun {
                        session_id: &SessionId(current_session_id.clone()),
                        turn_id: &compaction_turn,
                        model: &model,
                        config: &compaction_config,
                        provider: &provider,
                        native_request,
                        native_replay: &mut manual_replay,
                        reason: crate::CompactionReason::Manual,
                        tokens_before,
                        focus_instructions: instructions,
                        log: &mut session_log,
                        pending_events: &mut pending_events,
                        tool_event_store: Some(&store),
                        review_tx: &tx,
                        cancellation: CancellationToken::new(),
                    },
                )
                .await;
                if result.is_ok() {
                    publish_native_replay(&native_replay, manual_replay.clone());
                }
                match result {
                    Ok(application) => refresh_manual_compaction_views(
                        application,
                        &tx,
                        &session_log,
                        context_budget(Some(&provider), project_root.as_deref()),
                    ),
                    Err(error) => {
                        let _ = tx.send(BackendEvent::Server(ServerEvent::StatusUpdated {
                            message: format!(
                                "manual compaction failed: {}",
                                provider_round_error_label(&error)
                            ),
                        }));
                    }
                }
            }
            ClientEvent::PromptSubmitted { session_id, prompt } => {
                if prompt.trim().is_empty() {
                    let _ = tx.send(BackendEvent::Server(ServerEvent::StatusUpdated {
                        message: String::from("empty prompt ignored"),
                    }));
                    continue;
                }
                let prompt_turn_index = turn_index;
                turn_index = turn_index.saturating_add(1);
                local_edit_index = local_edit_index.max(turn_index);
                if let Some(provider) = provider.clone() {
                    if active_provider_turn
                        .as_ref()
                        .is_some_and(|active| active.handle.is_finished())
                    {
                        active_provider_turn = None;
                    }
                    if active_provider_turn.is_some() {
                        let _ = tx.send(BackendEvent::Server(ServerEvent::StatusUpdated {
                            message: String::from("native provider: prompt already in progress"),
                        }));
                        continue;
                    }
                    let prompt_started = Instant::now();
                    let Some(started_prompt) = start_native_prompt(
                        &tx,
                        &store,
                        &mut session_log,
                        PromptSessionInput {
                            current_session_id: &current_session_id,
                            requested_session_id: session_id,
                        },
                        prompt,
                        prompt_turn_index,
                        prompt_started,
                    ) else {
                        continue;
                    };
                    let turn_id = started_prompt.turn.clone();
                    let requester = make_requester(&provider);
                    let (review_decision_tx, review_decision_rx) = mpsc::unbounded_channel();
                    let cancellation = CancellationToken::new();
                    let handle = tokio::spawn(handle_started_native_provider_prompt(
                        NativeProviderPromptTask {
                            tx: tx.clone(),
                            store: store.clone(),
                            provider,
                            native_replay: native_replay.clone(),
                            started_prompt,
                            project_runtime: ProviderPromptProjectRuntime {
                                project_context: provider_project_context.clone(),
                                extension_manifest_scan_state: extension_manifest_scan_state
                                    .clone(),
                                extension_activation_state: extension_activation_state.clone(),
                            },
                            review_decisions: review_decision_rx,
                            cancellation: cancellation.clone(),
                        },
                        requester,
                    ));
                    active_provider_turn = Some(ActiveProviderTurn {
                        handle,
                        turn_id,
                        prompt_started,
                        review_decision_tx,
                        cancellation,
                    });
                } else if let Some(setup_error) = provider_setup_error.as_deref() {
                    handle_native_prompt_unconfigured_provider(
                        &tx,
                        &store,
                        &mut session_log,
                        PromptSessionInput {
                            current_session_id: &current_session_id,
                            requested_session_id: session_id,
                        },
                        &UnconfiguredProviderPrompt {
                            prompt: &prompt,
                            turn_index: prompt_turn_index,
                            prompt_started: Instant::now(),
                            setup_error,
                        },
                    );
                } else {
                    let prompt_started = Instant::now();
                    handle_native_prompt(
                        &tx,
                        &store,
                        &mut session_log,
                        PromptSessionInput {
                            current_session_id: &current_session_id,
                            requested_session_id: session_id,
                        },
                        &prompt,
                        prompt_turn_index,
                        prompt_started,
                    );
                }
            }
            ClientEvent::ModelSelected { model } => {
                if provider_connections.is_some() {
                    send_model_change_failed(
                        &tx,
                        ModelChangeTarget {
                            model,
                            connection_id: None,
                            provider: None,
                            request_id: None,
                        },
                        String::from("model change rejected: connection selection is required"),
                    );
                } else {
                    apply_native_model_selection(
                        &tx,
                        &mut provider,
                        active_provider_turn.as_ref(),
                        None,
                        None,
                        model,
                    );
                }
            }
            ClientEvent::ModelSelectedDetailed {
                provider: selected_provider,
                model_id,
                connection_id,
                request_id,
            } => {
                let Some(runtime) = provider_connections.as_ref() else {
                    apply_native_model_selection(
                        &tx,
                        &mut provider,
                        active_provider_turn.as_ref(),
                        Some(&selected_provider),
                        Some(request_id),
                        model_id,
                    );
                    continue;
                };
                let target = ModelChangeTarget {
                    model: model_id.clone(),
                    connection_id: connection_id.clone(),
                    provider: Some(selected_provider.clone()),
                    request_id: Some(request_id),
                };
                if active_provider_turn
                    .as_ref()
                    .is_some_and(|active| !active.handle.is_finished())
                {
                    send_model_change_failed(
                        &tx,
                        target,
                        String::from("model change unavailable while a prompt is in progress"),
                    );
                    continue;
                }
                if connection_flow.mutation_in_flight() {
                    send_model_change_failed(
                        &tx,
                        target,
                        String::from(
                            "model change unavailable while a connection change is in progress",
                        ),
                    );
                    continue;
                }
                if activation_in_flight.is_some() {
                    send_model_change_failed(
                        &tx,
                        target,
                        String::from("model change already in progress"),
                    );
                    continue;
                }
                let Some(connection_id) = connection_id else {
                    send_model_change_failed(
                        &tx,
                        target,
                        String::from("model change rejected: connection is required"),
                    );
                    continue;
                };
                let Some(row) = advertised_catalog.iter().find(|entry| {
                    entry.info.connection_id.as_deref() == Some(connection_id.as_str())
                        && entry.info.id == model_id
                        && entry.info.provider == selected_provider
                }) else {
                    send_model_change_failed(
                        &tx,
                        target,
                        String::from("model change rejected: unknown connection model"),
                    );
                    continue;
                };
                let runtime_connection_id = if connection_id == "environment" {
                    ConnectionId::environment()
                } else {
                    let Ok(id) = ConnectionId::parse_stored(&connection_id) else {
                        send_model_change_failed(
                            &tx,
                            target,
                            String::from("model change rejected: invalid connection identity"),
                        );
                        continue;
                    };
                    id
                };
                debug_assert_eq!(
                    row.info.connection_id.as_deref(),
                    Some(connection_id.as_str())
                );
                activation_generation = activation_generation.wrapping_add(1);
                let generation = activation_generation;
                activation_in_flight = Some(InFlightModelActivation {
                    generation,
                    target: target.clone(),
                });
                let activation_update_tx = activation_update_tx.clone();
                let future = runtime.activate(runtime_connection_id, model_id);
                tokio::spawn(async move {
                    let _ = activation_update_tx.send((generation, target, future.await));
                });
            }
            ClientEvent::SessionSelected { session_id } => {
                if active_provider_turn.is_some() {
                    let _ = tx.send(BackendEvent::Server(ServerEvent::StatusUpdated {
                        message: String::from("cannot switch sessions during an active prompt"),
                    }));
                    continue;
                }
                let selected_path = session_path_for_id_in_dir(session_path.parent(), &session_id);
                let Some(selected_path) = selected_path else {
                    let _ = tx.send(BackendEvent::Server(ServerEvent::StatusUpdated {
                        message: format!("unknown session {session_id}"),
                    }));
                    continue;
                };
                if !session_path_is_selectable(&selected_path, &session_path) {
                    let _ = tx.send(BackendEvent::Server(ServerEvent::StatusUpdated {
                        message: format!("unknown session {session_id}"),
                    }));
                    continue;
                }
                switch_native_session(
                    &tx,
                    selected_path,
                    SessionSwitchState {
                        current_session_path: &mut session_path,
                        current_session_id: &mut current_session_id,
                        store: &mut store,
                        native_replay: &native_replay,
                        session_log: &mut session_log,
                        turn_index: &mut turn_index,
                        local_edit_index: &mut local_edit_index,
                    },
                    context_budget(provider.as_ref(), project_root.as_deref()),
                )
                .await;
            }
            ClientEvent::SessionPathSelected {
                session_path: selected_session_path,
            } => {
                if active_provider_turn.is_some() {
                    let _ = tx.send(BackendEvent::Server(ServerEvent::StatusUpdated {
                        message: String::from("cannot switch sessions during an active prompt"),
                    }));
                    continue;
                }
                let selected_path = PathBuf::from(&selected_session_path);
                if !session_path_is_selectable(&selected_path, &session_path) {
                    let _ = tx.send(BackendEvent::Server(ServerEvent::StatusUpdated {
                        message: format!("unknown session path {selected_session_path}"),
                    }));
                    continue;
                }
                switch_native_session(
                    &tx,
                    selected_path,
                    SessionSwitchState {
                        current_session_path: &mut session_path,
                        current_session_id: &mut current_session_id,
                        store: &mut store,
                        native_replay: &native_replay,
                        session_log: &mut session_log,
                        turn_index: &mut turn_index,
                        local_edit_index: &mut local_edit_index,
                    },
                    context_budget(provider.as_ref(), project_root.as_deref()),
                )
                .await;
            }
            ClientEvent::ForkMessagesRequested | ClientEvent::SessionForkRequested { .. } => {
                let _ = tx.send(BackendEvent::Server(ServerEvent::StatusUpdated {
                    message: String::from("fork/session tree UI is not available yet"),
                }));
            }
            ClientEvent::ThinkingLevelSelected { level } => {
                let _ = tx.send(BackendEvent::Server(ServerEvent::ThinkingLevelApplied {
                    level,
                }));
            }
            ClientEvent::LocalEditPrepareRequested {
                request_id,
                operation,
            } => {
                let edit_turn_index = local_edit_index.max(turn_index);
                local_edit_index = edit_turn_index.saturating_add(1);
                turn_index = turn_index.max(local_edit_index);
                handle_native_local_edit_prepare(
                    &tx,
                    &store,
                    &mut edit_access,
                    edit_root.as_ref(),
                    LocalEditPrepareInput {
                        session_id: SessionId(current_session_id.clone()),
                        request_id,
                        operation,
                        turn_index: edit_turn_index,
                    },
                );
            }
            ClientEvent::LocalEditDecisionSubmitted {
                preview_id,
                permission_decision_id,
                decision,
            } => {
                handle_native_local_edit_decision(
                    &tx,
                    &store,
                    &mut edit_access,
                    preview_id,
                    permission_decision_id,
                    decision,
                );
            }
            ClientEvent::ToolReviewDecisionSubmitted {
                request_id,
                preview_id,
                permission_decision_id,
                decision,
            } => {
                let decision = AgentEditReviewDecision {
                    request_id,
                    preview_id,
                    permission_decision_id,
                    decision,
                };
                let forwarded = active_provider_turn
                    .as_ref()
                    .is_some_and(|active| active.review_decision_tx.send(decision).is_ok());
                if !forwarded {
                    let _ = tx.send(BackendEvent::Server(ServerEvent::StatusUpdated {
                        message: String::from("native provider: stale tool review decision"),
                    }));
                }
            }
            ClientEvent::ExtensionLifecycleRequested {
                request_id,
                action,
                selector,
            } => {
                handle_native_extension_lifecycle_request(
                    &tx,
                    &extension_manifest_scan_state,
                    &extension_activation_state,
                    request_id,
                    action,
                    &selector,
                )
                .await;
            }
            ClientEvent::ExtensionDiagnosticSnapshotRequested {
                request_id,
                selector,
            } => {
                handle_native_extension_diagnostic_snapshot_request(
                    &tx,
                    &extension_activation_state,
                    request_id,
                    selector.as_deref(),
                )
                .await;
            }
            ClientEvent::ConnectionsRequested => {
                if !first_render_completed {
                    let _ = tx.send(BackendEvent::Server(ServerEvent::StatusUpdated {
                        message: String::from(
                            "provider connections are available after the first render",
                        ),
                    }));
                } else if provider_connections.is_some() {
                    let effects = connection_flow.open();
                    apply_connection_flow_effects(
                        effects,
                        ConnectionFlowEffectContext {
                            runtime: provider_connections.as_ref(),
                            tx: &tx,
                            flow: &connection_flow,
                            provider: provider.as_ref(),
                            connection_updates: &connection_update_tx,
                            model_refresh_updates: &connection_model_refresh_tx,
                            model_refresh_generation: &mut connection_model_refresh_generation,
                            model_refresh_in_flight: &mut connection_model_refresh_in_flight,
                            model_refresh_pending: &mut connection_model_refresh_pending,
                            activation_generation: &mut activation_generation,
                            activation_in_flight: &mut activation_in_flight,
                        },
                    );
                } else {
                    let _ = tx.send(BackendEvent::Server(ServerEvent::StatusUpdated {
                        message: String::from("provider connection setup is unavailable"),
                    }));
                }
            }
            ClientEvent::DialogResolved {
                dialog_id,
                response,
            } => {
                if first_render_completed && is_provider_connection_dialog_id(&dialog_id) {
                    let provider_turn_active = active_provider_turn
                        .as_ref()
                        .is_some_and(|active| !active.handle.is_finished());
                    let effects = connection_flow.handle_dialog_response(
                        &dialog_id,
                        response,
                        provider_turn_active,
                    );
                    apply_connection_flow_effects(
                        effects,
                        ConnectionFlowEffectContext {
                            runtime: provider_connections.as_ref(),
                            tx: &tx,
                            flow: &connection_flow,
                            provider: provider.as_ref(),
                            connection_updates: &connection_update_tx,
                            model_refresh_updates: &connection_model_refresh_tx,
                            model_refresh_generation: &mut connection_model_refresh_generation,
                            model_refresh_in_flight: &mut connection_model_refresh_in_flight,
                            model_refresh_pending: &mut connection_model_refresh_pending,
                            activation_generation: &mut activation_generation,
                            activation_in_flight: &mut activation_in_flight,
                        },
                    );
                }
            }
            ClientEvent::WidgetCleared { .. } => {}
        }
    }
}

fn session_path_for_id_in_dir(session_dir: Option<&Path>, session_id: &str) -> Option<PathBuf> {
    if session_id.is_empty() || session_id == "." || session_id == ".." {
        return None;
    }
    if session_id.contains('/') || session_id.contains('\\') {
        return None;
    }
    Some(session_dir?.join(format!("{session_id}.jsonl")))
}

fn session_path_is_selectable(selected_session_path: &Path, current_session_path: &Path) -> bool {
    session_id_from_log_path(selected_session_path).is_some()
        && selected_session_path.exists()
        && selected_session_path.parent() == current_session_path.parent()
}

async fn switch_native_session(
    tx: &mpsc::UnboundedSender<BackendEvent>,
    selected_path: PathBuf,
    state: SessionSwitchState<'_>,
    context_budget: Option<crate::ContextBudget>,
) {
    let SessionSwitchState {
        current_session_path,
        current_session_id,
        store,
        native_replay,
        session_log,
        turn_index,
        local_edit_index,
    } = state;
    let Some(selected_session_id) = session_id_from_log_path(&selected_path) else {
        let _ = tx.send(BackendEvent::Server(ServerEvent::StatusUpdated {
            message: format!("unknown session path {}", selected_path.display()),
        }));
        return;
    };
    let selected_store = JsonlSessionStore::new(selected_path.clone());
    let load_store = selected_store.clone();
    let loaded = match tokio::task::spawn_blocking(move || load_store.load_with_warnings()).await {
        Ok(Ok(load)) => session_state_from_load_result(tx, Ok(load)),
        Ok(Err(error)) => {
            let _ = tx.send(BackendEvent::Server(ServerEvent::StatusUpdated {
                message: format!("failed to load session log: {error}"),
            }));
            return;
        }
        Err(error) => {
            let _ = tx.send(BackendEvent::Server(ServerEvent::StatusUpdated {
                message: format!("failed to load session log: {error}"),
            }));
            return;
        }
    };
    *current_session_path = selected_path;
    current_session_id.clone_from(&selected_session_id);
    *store = selected_store;
    *session_log = loaded;
    *turn_index = session_log.next_turn_index();
    *local_edit_index = *turn_index;
    if let Ok(mut replay) = native_replay.lock() {
        *replay = crate::responses_replay::NativeReplayStoreState::Uninitialized;
    }
    let _ = tx.send(BackendEvent::Server(ServerEvent::SessionChanged {
        session_id: selected_session_id,
    }));
    send_native_session_messages_from_log(tx, session_log);
    send_native_session_stats_from_log(tx, session_log, context_budget);
}

fn send_native_initial_state(
    tx: &mpsc::UnboundedSender<BackendEvent>,
    session_id: &str,
    session_path: &Path,
    provider: Option<&ProviderConfig>,
    provider_setup_error: Option<&str>,
) {
    let session_file = Some(session_path.to_string_lossy().into_owned());
    let _ = tx.send(BackendEvent::Server(ServerEvent::Ready {
        handshake: Handshake::new(
            "yach-native",
            vec![
                Capability::PromptStreaming,
                Capability::PromptCancellation,
                Capability::LocalEdit,
                Capability::ExtensionLifecycle,
                Capability::FirstRenderEvents,
                Capability::ToolOutputStreaming,
            ],
        ),
    }));
    let active = active_model(provider, provider_setup_error);
    let _ = tx.send(BackendEvent::Server(ServerEvent::StateUpdated(
        BackendState {
            model_id: Some(active.id),
            model_name: Some(active.name),
            model_provider: Some(active.provider),
            model_connection_id: provider
                .and_then(|provider| provider.connection_id.as_ref())
                .map(|id| id.as_str().to_owned()),
            session_id: Some(session_id.to_owned()),
            session_file,
            thinking_level: Some(String::from("low")),
            is_streaming: false,
            is_compacting: false,
            message_count: session_message_count(session_path),
            pending_message_count: Some(0),
        },
    )));
    let _ = tx.send(BackendEvent::Server(ServerEvent::StatusUpdated {
        message: backend_status_message(provider, provider_setup_error),
    }));
    send_native_models(tx, provider, provider_setup_error);
}

/// Switch the runner's provider model between turns. Refused while a
/// prompt is in progress (the active turn cloned the old config) and when
/// the selection names a different provider than the configured one.
///
/// Rehydrates the adapter config's `context_window`, `max_tokens`, and
/// `max_tokens_param` from the selected model's catalog entry when one is
/// found — fixing a stale-window/budget bug where switching models used
/// to leave the PREVIOUS model's numbers in effect under the new model's
/// name. `provider_config.adapter` is read directly by `context_budget`
/// (the context-meter budget) and by the per-turn provider request
/// builder (both via `make_requester`/`ProviderAgentToolRound`) on every
/// subsequent turn, so mutating it here is what makes the fix take effect
/// starting with the next prompt — no separate propagation step needed.
/// When the id isn't in the catalog list (unlisted id, or no catalog
/// list at all), the current adapter values are left untouched — a floor,
/// not a reset, since there is no better data to move to.
fn apply_native_model_selection(
    tx: &mpsc::UnboundedSender<BackendEvent>,
    provider: &mut Option<ProviderConfig>,
    active_provider_turn: Option<&ActiveProviderTurn>,
    selected_provider: Option<&str>,
    request_id: Option<u64>,
    model: String,
) {
    if active_provider_turn.is_some_and(|active| !active.handle.is_finished()) {
        send_model_change_failed(
            tx,
            model_change_target(&model, None, selected_provider, request_id),
            String::from("model change unavailable while a prompt is in progress"),
        );
        return;
    }
    let Some(provider_config) = provider.as_mut() else {
        let _ = tx.send(BackendEvent::Server(ServerEvent::ModelChanged(
            ModelChangeTarget {
                model,
                connection_id: None,
                provider: None,
                request_id,
            },
        )));
        return;
    };
    if let Some(selected_provider) = selected_provider
        && selected_provider != provider_config.provider_label()
    {
        send_model_change_failed(
            tx,
            model_change_target(&model, None, Some(selected_provider), request_id),
            format!(
                "model change rejected: provider {selected_provider} is not the configured \
provider ({})",
                provider_config.provider_label()
            ),
        );
        return;
    }
    if let Some(entry) = provider_config
        .catalog_models
        .iter()
        .find(|entry| entry.info.id == model)
    {
        let Some(adapter) = Arc::get_mut(&mut provider_config.adapter) else {
            send_model_change_failed(
                tx,
                model_change_target(&model, None, selected_provider, request_id),
                String::from("model change unavailable while provider configuration is in use"),
            );
            return;
        };
        adapter.context_window = entry.context_window;
        adapter.max_tokens = entry.output_budget;
        adapter.max_tokens_param = entry.max_tokens_param;
        provider_config.responses_compact = entry.responses_compact;
    } else {
        // Retain numeric adapter floors but clear capability for an unlisted
        // id—stale `true` would be unsafe.
        provider_config.responses_compact = None;
    }
    provider_config.model.clone_from(&model);
    let _ = tx.send(BackendEvent::Server(ServerEvent::StatusUpdated {
        message: format!("model changed to {model}"),
    }));
    let _ = tx.send(BackendEvent::Server(ServerEvent::ModelChanged(
        ModelChangeTarget {
            model,
            connection_id: None,
            provider: None,
            request_id,
        },
    )));
}

fn send_native_models(
    tx: &mpsc::UnboundedSender<BackendEvent>,
    provider: Option<&ProviderConfig>,
    provider_setup_error: Option<&str>,
) {
    let active = active_model(provider, provider_setup_error);
    let entries = provider.map_or(&[][..], |provider| provider.catalog_models.as_ref());
    publish_native_model_snapshots(tx, &active, entries);
}

/// Emits a runtime-owned catalog snapshot without mutating the active provider
/// configuration. The connection runtime may complete after a newer refresh;
/// generation filtering happens before this helper is called.
fn send_native_models_with_catalog(
    tx: &mpsc::UnboundedSender<BackendEvent>,
    provider: Option<&ProviderConfig>,
    provider_setup_error: Option<&str>,
    catalog: Option<&[CatalogModelEntry]>,
) {
    let active = active_model(provider, provider_setup_error);
    let entries = catalog
        .unwrap_or_else(|| provider.map_or(&[][..], |provider| provider.catalog_models.as_ref()));
    publish_native_model_snapshots(tx, &active, entries);
}

/// Publishes the default and complete picker views from one immutable catalog
/// snapshot. The active row is deliberately prepended to both views, including
/// when a provider returned an otherwise unknown model id.
fn publish_native_model_snapshots(
    tx: &mpsc::UnboundedSender<BackendEvent>,
    active: &ModelInfo,
    entries: &[CatalogModelEntry],
) {
    let active = active_environment_catalog_model(active, entries.iter().map(|entry| &entry.info));
    let curated = native_models_from_catalog(
        active,
        entries
            .iter()
            .filter(|entry| entry.curated)
            .map(|entry| &entry.info),
    );
    let complete = native_models_from_catalog(active, entries.iter().map(|entry| &entry.info));
    let _ = tx.send(BackendEvent::Server(ServerEvent::AvailableModelsUpdated {
        models: curated,
    }));
    let _ = tx.send(BackendEvent::Server(ServerEvent::DiscoveredModelsUpdated {
        models: complete,
    }));
}

/// `active` first, then the rest of the CLI-supplied catalog list minus
/// the active id, in the caller's (catalog `BTreeMap`) order. The head
/// entry's `name` comes from the supplied list when the active model
/// appears there, since `active_model`'s own `name` falls back to the
/// raw id — this is how the resolved display name reaches the head slot.
fn native_models_from_catalog<'a, I>(active: &ModelInfo, catalog_models: I) -> Vec<ModelInfo>
where
    I: IntoIterator<Item = &'a ModelInfo> + Clone,
{
    let head = catalog_models
        .clone()
        .into_iter()
        .find(|model| same_model_target(active, model))
        .cloned()
        .unwrap_or_else(|| active.clone());
    let mut models = vec![head];
    models.extend(
        catalog_models
            .into_iter()
            .filter(|model| !same_model_target(active, model))
            .cloned(),
    );
    models
}

fn active_environment_catalog_model<'a, I>(
    active: &'a ModelInfo,
    catalog_models: I,
) -> &'a ModelInfo
where
    I: IntoIterator<Item = &'a ModelInfo>,
{
    catalog_models
        .into_iter()
        .find(|candidate| {
            candidate.id == active.id
                && candidate.provider == active.provider
                && candidate.connection_id.as_deref() == Some("environment")
        })
        .unwrap_or(active)
}

fn same_model_target(left: &ModelInfo, right: &ModelInfo) -> bool {
    match (&left.connection_id, &right.connection_id) {
        (None, None) => left.id == right.id,
        _ => {
            left.id == right.id
                && left.provider == right.provider
                && left.connection_id == right.connection_id
        }
    }
}

fn active_model(
    provider: Option<&ProviderConfig>,
    provider_setup_error: Option<&str>,
) -> ModelInfo {
    let Some(provider) = provider else {
        if provider_setup_error.is_some() {
            return ModelInfo {
                id: String::from("provider-unconfigured"),
                name: String::from("Provider Not Configured"),
                provider: String::from("native"),
                connection_id: None,
                connection_display: None,
            };
        }
        return ModelInfo {
            id: String::from("fixture-echo"),
            name: String::from("Fixture Echo"),
            provider: String::from("native"),
            connection_id: None,
            connection_display: None,
        };
    };
    let provider_label = provider.provider_label();
    let id = provider.model.clone();
    ModelInfo {
        name: id.clone(),
        id,
        provider: provider_label.to_owned(),
        connection_id: provider
            .connection_id
            .as_ref()
            .map(|id| id.as_str().to_owned()),
        connection_display: provider.connection_display.clone(),
    }
}

fn backend_status_message(
    provider: Option<&ProviderConfig>,
    provider_setup_error: Option<&str>,
) -> String {
    if let Some(provider) = provider {
        let model = active_model(Some(provider), None);
        format!(
            "backend: {}/{}; read/search/list and exact/create edit tools available",
            model.provider, model.id
        )
    } else if let Some(setup_error) = provider_setup_error {
        format!("{setup_error}; set the provider environment and relaunch yach tui")
    } else {
        String::from(
            "backend: no provider configured; local read-only project inspection available",
        )
    }
}

fn handle_native_prompt(
    tx: &mpsc::UnboundedSender<BackendEvent>,
    store: &JsonlSessionStore,
    log: &mut SessionLog,
    session: PromptSessionInput<'_>,
    prompt: &str,
    turn_index: u64,
    prompt_started: Instant,
) {
    let session_id =
        if session.requested_session_id.is_empty() || session.requested_session_id == "default" {
            session.current_session_id.to_owned()
        } else {
            session.requested_session_id
        };
    if session_id != session.current_session_id {
        let _ = tx.send(BackendEvent::Server(ServerEvent::StatusUpdated {
            message: format!("unknown session {session_id}"),
        }));
        return;
    }
    let typed_session_id = SessionId(session_id.clone());

    let turn_id = TurnId(format!("turn-{turn_index}"));
    let user_entry_id = EntryId(format!("entry-{turn_index}-user"));
    let assistant_entry_id = EntryId(format!("entry-{turn_index}-assistant"));
    let response = format!("fixture response: {prompt}");
    let fixture_outcome = fixture_outcome(prompt);
    let mut pending_events = Vec::new();
    push_native_session_event(
        log,
        &mut pending_events,
        SessionEvent::EntryAppended {
            session_id: typed_session_id.clone(),
            entry_id: user_entry_id.clone(),
            parent_entry_id: None,
            turn_id: turn_id.clone(),
            role: Role::User,
            text: prompt.to_owned(),
            provider: None,
        },
    );

    let _ = tx.send(BackendEvent::Server(ServerEvent::StatusUpdated {
        message: String::from("turn_start"),
    }));

    if let Err(error) = append_pending_native_session_events(store, &mut pending_events) {
        let _ = tx.send(BackendEvent::Server(ServerEvent::StatusUpdated {
            message: format!("failed to persist session log: {error}"),
        }));
    }

    match fixture_outcome {
        FixtureOutcome::Completed => {
            for delta in response_chunks(&response) {
                if tx
                    .send(BackendEvent::Server(ServerEvent::PromptDelta {
                        session_id: session_id.clone(),
                        delta,
                    }))
                    .is_err()
                {
                    push_native_prompt_total_metric(
                        log,
                        &mut pending_events,
                        &typed_session_id,
                        &turn_id,
                        prompt_started,
                    );
                    push_native_session_event(
                        log,
                        &mut pending_events,
                        SessionEvent::TurnFinished {
                            session_id: typed_session_id.clone(),
                            turn_id,
                            outcome: TurnOutcome::Cancelled,
                            reason: Some(String::from("ui receiver dropped")),
                        },
                    );
                    let _ = append_pending_native_session_events(store, &mut pending_events);
                    return;
                }
            }
            push_native_prompt_total_metric(
                log,
                &mut pending_events,
                &typed_session_id,
                &turn_id,
                prompt_started,
            );
            push_native_session_event(
                log,
                &mut pending_events,
                SessionEvent::EntryAppended {
                    session_id: typed_session_id.clone(),
                    entry_id: assistant_entry_id,
                    parent_entry_id: Some(user_entry_id),
                    turn_id: turn_id.clone(),
                    role: Role::Assistant,
                    text: response,
                    provider: None,
                },
            );
            push_native_session_event(
                log,
                &mut pending_events,
                SessionEvent::TurnFinished {
                    session_id: typed_session_id.clone(),
                    turn_id,
                    outcome: TurnOutcome::Completed,
                    reason: None,
                },
            );
        }
        FixtureOutcome::Failed => {
            push_native_prompt_total_metric(
                log,
                &mut pending_events,
                &typed_session_id,
                &turn_id,
                prompt_started,
            );
            persist_native_fixture_error(
                tx,
                log,
                &mut pending_events,
                &typed_session_id,
                turn_id,
                TurnOutcome::Failed,
                &ProviderError::fixture_failure(),
            );
        }
        FixtureOutcome::Malformed => {
            push_native_prompt_total_metric(
                log,
                &mut pending_events,
                &typed_session_id,
                &turn_id,
                prompt_started,
            );
            persist_native_fixture_error(
                tx,
                log,
                &mut pending_events,
                &typed_session_id,
                turn_id,
                TurnOutcome::Failed,
                &ProviderError::malformed_stream("fixture malformed stream"),
            );
        }
        FixtureOutcome::Cancelled => {
            push_native_prompt_total_metric(
                log,
                &mut pending_events,
                &typed_session_id,
                &turn_id,
                prompt_started,
            );
            persist_native_fixture_error(
                tx,
                log,
                &mut pending_events,
                &typed_session_id,
                turn_id,
                TurnOutcome::Cancelled,
                &ProviderError::cancelled("fixture cancellation"),
            );
        }
    }

    let status = match append_pending_native_session_events(store, &mut pending_events) {
        Ok(()) => fixture_outcome.status_message().to_owned(),
        Err(error) => format!("failed to persist session log: {error}"),
    };
    let outcome = fixture_outcome.prompt_outcome();
    let _ = tx.send(BackendEvent::Server(ServerEvent::StatusUpdated {
        message: status.clone(),
    }));
    let _ = tx.send(BackendEvent::Server(ServerEvent::PromptFinished {
        session_id,
        outcome,
        message: Some(status),
    }));
    send_native_session_stats_from_log(tx, log, None);
}

/// Prompt details for a native session whose provider could not be configured.
struct UnconfiguredProviderPrompt<'a> {
    prompt: &'a str,
    turn_index: u64,
    prompt_started: Instant,
    setup_error: &'a str,
}

/// Fail a submitted prompt with the provider setup error instead of producing
/// fixture output, so an unconfigured launch stays honest and recoverable.
fn handle_native_prompt_unconfigured_provider(
    tx: &mpsc::UnboundedSender<BackendEvent>,
    store: &JsonlSessionStore,
    log: &mut SessionLog,
    session: PromptSessionInput<'_>,
    prompt: &UnconfiguredProviderPrompt<'_>,
) {
    let session_id =
        if session.requested_session_id.is_empty() || session.requested_session_id == "default" {
            session.current_session_id.to_owned()
        } else {
            session.requested_session_id
        };
    if session_id != session.current_session_id {
        let _ = tx.send(BackendEvent::Server(ServerEvent::StatusUpdated {
            message: format!("unknown session {session_id}"),
        }));
        return;
    }
    let typed_session_id = SessionId(session_id);

    let turn_id = TurnId(format!("turn-{}", prompt.turn_index));
    let user_entry_id = EntryId(format!("entry-{}-user", prompt.turn_index));
    let mut pending_events = Vec::new();
    push_native_session_event(
        log,
        &mut pending_events,
        SessionEvent::EntryAppended {
            session_id: typed_session_id.clone(),
            entry_id: user_entry_id,
            parent_entry_id: None,
            turn_id: turn_id.clone(),
            role: Role::User,
            text: prompt.prompt.to_owned(),
            provider: None,
        },
    );
    push_native_prompt_total_metric(
        log,
        &mut pending_events,
        &typed_session_id,
        &turn_id,
        prompt.prompt_started,
    );
    push_native_session_event(
        log,
        &mut pending_events,
        SessionEvent::TurnFinished {
            session_id: typed_session_id.clone(),
            turn_id,
            outcome: TurnOutcome::Failed,
            reason: Some(format!("provider_unconfigured {}", prompt.setup_error)),
        },
    );
    finish_native_prompt(
        tx,
        store,
        log,
        &mut pending_events,
        PromptCompletion {
            session_id: &typed_session_id.0,
            status: &format!(
                "{}; set the provider environment and relaunch yach tui",
                prompt.setup_error
            ),
            outcome: PromptOutcome::Failed,
            context_budget: None,
        },
    );
}

#[derive(Debug, Clone)]
struct StartedPrompt {
    session_id: SessionId,
    prompt: String,
    log: SessionLog,
    pending_events: Vec<SessionEvent>,
    turn: TurnId,
    user_entry: EntryId,
    assistant_entry: EntryId,
    prompt_started: Instant,
}

fn start_native_prompt(
    tx: &mpsc::UnboundedSender<BackendEvent>,
    store: &JsonlSessionStore,
    log: &mut SessionLog,
    session: PromptSessionInput<'_>,
    prompt: String,
    turn_index: u64,
    prompt_started: Instant,
) -> Option<StartedPrompt> {
    let session_id =
        if session.requested_session_id.is_empty() || session.requested_session_id == "default" {
            session.current_session_id.to_owned()
        } else {
            session.requested_session_id
        };
    if session_id != session.current_session_id {
        let _ = tx.send(BackendEvent::Server(ServerEvent::StatusUpdated {
            message: format!("unknown session {session_id}"),
        }));
        return None;
    }
    let typed_session_id = SessionId(session_id);

    let turn = TurnId(format!("turn-{turn_index}"));
    let user_entry = EntryId(format!("entry-{turn_index}-user"));
    let assistant_entry = EntryId(format!("entry-{turn_index}-assistant"));
    let mut pending_events = Vec::new();
    push_native_session_event(
        log,
        &mut pending_events,
        SessionEvent::EntryAppended {
            session_id: typed_session_id.clone(),
            entry_id: user_entry.clone(),
            parent_entry_id: None,
            turn_id: turn.clone(),
            role: Role::User,
            text: prompt.clone(),
            provider: None,
        },
    );

    let _ = tx.send(BackendEvent::Server(ServerEvent::StatusUpdated {
        message: String::from("turn_start"),
    }));

    if let Err(error) = append_pending_native_session_events(store, &mut pending_events) {
        let _ = tx.send(BackendEvent::Server(ServerEvent::StatusUpdated {
            message: format!("failed to persist session log: {error}"),
        }));
        return None;
    }

    Some(StartedPrompt {
        session_id: typed_session_id,
        prompt,
        log: log.clone(),
        pending_events,
        turn,
        user_entry,
        assistant_entry,
        prompt_started,
    })
}

fn push_native_session_event(
    log: &mut SessionLog,
    pending_events: &mut Vec<SessionEvent>,
    event: SessionEvent,
) {
    log.push(event.clone());
    pending_events.push(event);
}

fn push_native_prompt_total_metric(
    log: &mut SessionLog,
    pending_events: &mut Vec<SessionEvent>,
    session_id: &SessionId,
    turn_id: &TurnId,
    prompt_started: Instant,
) {
    push_native_session_event(
        log,
        pending_events,
        duration_metric_event(
            session_id.clone(),
            Some(turn_id.clone()),
            "prompt_total",
            prompt_started.elapsed(),
        ),
    );
}

fn duration_metric_event(
    session_id: SessionId,
    turn_id: Option<TurnId>,
    name: impl Into<String>,
    duration: Duration,
) -> SessionEvent {
    let duration_ms = u64::try_from(duration.as_millis()).unwrap_or(u64::MAX);
    SessionEvent::MetricRecorded {
        session_id,
        turn_id,
        metric: DurationMetric {
            name: name.into(),
            duration_ms,
            attributes: Vec::new(),
        },
    }
}

/// Compact one-line-per-message rendering of provider context for shape
/// assertions and diagnostics (the Codex snapshot pattern): `role:prefix`.
#[must_use]
pub fn provider_message_shapes(messages: &[ProviderMessage]) -> Vec<String> {
    messages
        .iter()
        .map(|message| {
            let role = match message.role {
                Role::User => "user",
                Role::Assistant => "assistant",
                Role::Tool => "tool",
                Role::System => "system",
            };
            let prefix: String = message
                .content
                .lines()
                .next()
                .unwrap_or_default()
                .chars()
                .take(48)
                .collect();
            format!("{role}:{}", prefix.trim_end())
        })
        .collect()
}

/// Continuation frame wrapping a compaction summary in provider context.
fn compaction_summary_message(summary: &str) -> ProviderMessage {
    ProviderMessage::text(
        Role::System,
        format!(
            "Earlier work in this session was compacted. The summary below is \
authoritative for everything before the messages that follow it.\n\n{summary}"
        ),
    )
}

fn provider_messages_from_log(log: &SessionLog, current_turn_id: &TurnId) -> Vec<ProviderMessage> {
    let checkpoint = crate::compaction::newest_compaction_checkpoint(log);
    let kept_events = checkpoint.as_ref().map_or(&log.events[..], |view| {
        &log.events[view.kept_start_index.min(log.events.len())..]
    });
    provider_messages_from_event_slice(
        log,
        kept_events,
        current_turn_id,
        checkpoint.as_ref().map(|view| view.summary),
    )
}

/// Convert a selected event slice using completed-turn knowledge from the
/// complete log. `provider_messages_from_log` deliberately remains the one
/// summary path so its historical conversion remains byte-identical.
fn provider_messages_from_event_slice(
    complete_log: &SessionLog,
    events: &[SessionEvent],
    current_turn_id: &TurnId,
    checkpoint_summary: Option<&str>,
) -> Vec<ProviderMessage> {
    let mut successful_entry_turns = std::collections::HashSet::new();
    let mut terminal_tool_turns = std::collections::HashSet::new();
    for event in &complete_log.events {
        let SessionEvent::TurnFinished {
            turn_id, outcome, ..
        } = event
        else {
            continue;
        };
        match outcome {
            TurnOutcome::Completed => {
                successful_entry_turns.insert(turn_id);
                terminal_tool_turns.insert(turn_id);
            }
            TurnOutcome::Failed | TurnOutcome::Cancelled => {
                terminal_tool_turns.insert(turn_id);
            }
        }
    }

    // (turn id, tool_request_id) -> (tool name, argument json, call id)
    let mut tool_context_by_request_id: std::collections::HashMap<ToolContextKey, ToolContext> =
        std::collections::HashMap::new();
    let mut messages = checkpoint_summary
        .map(|summary| vec![compaction_summary_message(summary)])
        .unwrap_or_default();
    messages.extend(events.iter().flat_map(|event| match event {
        SessionEvent::EntryAppended {
            turn_id,
            role,
            text,
            ..
        } if turn_id == current_turn_id || successful_entry_turns.contains(turn_id) => {
            vec![ProviderMessage::text(*role, text.clone())]
        }
        SessionEvent::ToolRequestRecorded {
            turn_id,
            tool_request_id,
            tool_name,
            provider_call_id,
            argument_content,
            ..
        } if turn_id == current_turn_id || terminal_tool_turns.contains(turn_id) => {
            let call_id = provider_call_id
                .clone()
                .unwrap_or_else(|| format!("yach-{}", tool_request_id.0));
            tool_context_by_request_id.insert(
                (turn_id.clone(), tool_request_id.0.clone()),
                (tool_name.clone(), argument_content.clone(), call_id),
            );
            Vec::new()
        }
        SessionEvent::ToolExecutionFinished {
            turn_id,
            tool_request_id,
            result_content,
            ..
        } if turn_id == current_turn_id || terminal_tool_turns.contains(turn_id) => {
            let Some((tool_name, Some(arguments), call_id)) =
                tool_context_by_request_id.remove(&(turn_id.clone(), tool_request_id.0.clone()))
            else {
                return Vec::new();
            };
            let Some(arguments_json) = serde_json::from_str::<serde_json::Value>(&arguments).ok()
            else {
                return Vec::new();
            };
            let Some(result) = result_content.as_deref() else {
                return Vec::new();
            };
            vec![
                ProviderMessage::assistant(
                    String::new(),
                    vec![ProviderToolCall {
                        call_id: call_id.clone(),
                        name: tool_name,
                        arguments_json,
                    }],
                ),
                ProviderMessage::tool_results(vec![ProviderToolResultBlock {
                    call_id,
                    content: result.to_owned(),
                }]),
            ]
        }
        SessionEvent::EntryAppended { .. }
        | SessionEvent::ToolRequestRecorded { .. }
        | SessionEvent::ToolExecutionFinished { .. }
        | SessionEvent::TurnFinished { .. }
        | SessionEvent::MetricRecorded { .. }
        | SessionEvent::StaticContextIncluded { .. }
        | SessionEvent::PermissionDecisionRecorded { .. }
        | SessionEvent::EditTraceRecorded { .. }
        | SessionEvent::EditTransactionPrepared { .. }
        | SessionEvent::EditTransactionFinished { .. }
        | SessionEvent::CompactionCheckpoint { .. } => Vec::new(),
    }));
    messages
}

/// Baseline guardrails for every native-provider request, kept deliberately
/// small. Each sentence earned its place in dogfooding: without the first
/// two, cheap models assert filesystem state from stale in-conversation
/// memory and retry failed calls verbatim; without the last two, models
/// over-apply project instructions to conversational prompts (reading
/// orientation docs before answering "hello"). See
/// docs/project/records/2026-07-20-baseline-prompt-cohort-check.md.
const PROVIDER_BASELINE_GUIDANCE: &str = "You are a coding agent running in the yach harness. \
Files can change outside this conversation at any time: verify current state with \
a tool call before asserting or acting on remembered file contents. If a tool call \
fails because the target changed, already exists, or is missing, re-check the \
current state and adapt instead of repeating the call. Match effort to the \
request: answer greetings, small talk, and questions you can already answer \
directly, without tool calls. Project instructions in context describe how to \
carry out real work, not a checklist to run before every response.";

fn provider_baseline_guidance_message() -> ProviderMessage {
    ProviderMessage::text(Role::System, String::from(PROVIDER_BASELINE_GUIDANCE))
}

fn provider_messages_from_log_with_static_context(
    log: &SessionLog,
    current_turn_id: &TurnId,
    context: &StaticContextBundle,
) -> Vec<ProviderMessage> {
    let mut messages = vec![provider_baseline_guidance_message()];
    messages.extend(provider_messages_from_static_context(context));
    messages.extend(provider_messages_from_log(log, current_turn_id));
    messages
}

fn provider_messages_from_static_context(context: &StaticContextBundle) -> Vec<ProviderMessage> {
    if context.items.is_empty() {
        return Vec::new();
    }

    let system_content = render_static_context_items(context.items.iter().filter(|item| {
        matches!(
            item.placement,
            StaticContextPlacement::ProjectInstructions | StaticContextPlacement::AppendSystem
        )
    }));
    let background_content = render_static_context_items(
        context
            .items
            .iter()
            .filter(|item| item.placement == StaticContextPlacement::BackgroundContext),
    );

    let mut messages = Vec::new();
    if let Some(content) = system_content {
        messages.push(ProviderMessage::text(Role::System, content));
    }
    if let Some(content) = background_content {
        messages.push(ProviderMessage::text(Role::User, content));
    }
    messages
}

fn render_static_context_items<'a>(
    items: impl Iterator<Item = &'a StaticContextItem>,
) -> Option<String> {
    let content = items
        .map(|item| format!("# {}\n\n{}", item.title, item.content))
        .collect::<Vec<_>>()
        .join("\n\n");
    if content.is_empty() {
        None
    } else {
        Some(content)
    }
}

fn append_pending_native_session_events(
    store: &JsonlSessionStore,
    pending_events: &mut Vec<SessionEvent>,
) -> std::io::Result<()> {
    store.append_events(pending_events)?;
    pending_events.clear();
    Ok(())
}

fn log_has_finished_turn(log: &SessionLog, turn_id: &TurnId) -> bool {
    log.events.iter().any(|event| {
        matches!(
            event,
            SessionEvent::TurnFinished {
                turn_id: finished_turn_id,
                ..
            } if finished_turn_id == turn_id
        )
    })
}

#[derive(Debug, Clone)]
struct ProviderTurnRefs {
    session_id: SessionId,
    turn: TurnId,
    user_entry: EntryId,
    assistant_entry: EntryId,
    prompt_started: Instant,
}

trait ProviderRequester: Send {
    fn request(
        &mut self,
        request: ProviderRequest,
    ) -> BoxFuture<'_, Result<Vec<ProviderStreamEvent>, ProviderError>>;

    fn request_attempt(
        &mut self,
        request: ProviderRequest,
    ) -> BoxFuture<'_, Result<ProviderStreamAttempt, ProviderError>> {
        Box::pin(async move {
            self.request(request)
                .await
                .map(ProviderStreamAttempt::Complete)
        })
    }
}

struct RigProviderRequester {
    adapter: Arc<RigProviderAdapterConfig>,
    approved_tools: Vec<String>,
}

impl ProviderRequester for RigProviderRequester {
    fn request(
        &mut self,
        request: ProviderRequest,
    ) -> BoxFuture<'_, Result<Vec<ProviderStreamEvent>, ProviderError>> {
        let adapter = self.adapter.clone();
        let approved_tools = self.approved_tools.clone();
        Box::pin(async move {
            run_provider_request_with_approved_tools(&adapter, request, approved_tools).await
        })
    }

    fn request_attempt(
        &mut self,
        request: ProviderRequest,
    ) -> BoxFuture<'_, Result<ProviderStreamAttempt, ProviderError>> {
        let adapter = self.adapter.clone();
        let approved_tools = self.approved_tools.clone();
        Box::pin(async move {
            run_provider_request_attempt_with_approved_tools(&adapter, request, approved_tools)
                .await
        })
    }
}

