    trait TestUnwrap {
        type Output;

        fn test_unwrap(self) -> Self::Output;
    }

    impl<T, E> TestUnwrap for Result<T, E> {
        type Output = T;

        fn test_unwrap(self) -> Self::Output {
            assert!(self.is_ok());
            match self {
                Ok(value) => value,
                Err(_) => unreachable!(),
            }
        }
    }

    impl<T> TestUnwrap for Option<T> {
        type Output = T;

        fn test_unwrap(self) -> Self::Output {
            assert!(self.is_some());
            match self {
                Some(value) => value,
                None => unreachable!(),
            }
        }
    }

    trait TestExpectErr {
        type Error;

        fn test_expect_err(self) -> Self::Error;
    }

    impl<T, E> TestExpectErr for Result<T, E> {
        type Error = E;

        fn test_expect_err(self) -> Self::Error {
            assert!(self.is_err());
            match self {
                Ok(_) => unreachable!(),
                Err(error) => error,
            }
        }
    }

