    #[test]
    fn send_native_models_with_supplied_catalog_emits_active_first_without_duplicate() {
        let (tx, mut rx) = mpsc::unbounded_channel();
        let mut provider = provider_test_config();
        provider.model = String::from("claude-sonnet-5");
        provider.catalog_models = vec![
            catalog_entry("claude-sonnet-5", "Claude Sonnet 5", "anthropic"),
            catalog_entry("claude-opus-4-8", "Claude Opus 4.8", "anthropic"),
        ]
        .into();

        send_native_models(&tx, Some(&provider), None);

        let event = rx.try_recv();
        assert!(event.is_ok());
        let Ok(event) = event else {
            return;
        };
        assert!(matches!(
            event,
            BackendEvent::Server(ServerEvent::AvailableModelsUpdated { .. })
        ));
        let BackendEvent::Server(ServerEvent::AvailableModelsUpdated { models }) = event else {
            return;
        };
        // Active first, with the display name resolved by the supplied
        // catalog entry (not `active_model`'s raw-id fallback); the rest
        // of the supplied list minus the active id follows, no duplicate.
        assert_eq!(
            models,
            vec![
                ModelInfo {
                    id: String::from("claude-sonnet-5"),
                    name: String::from("Claude Sonnet 5"),
                    provider: String::from("anthropic"),
                    connection_id: None,
                    connection_display: None,
                },
                ModelInfo {
                    id: String::from("claude-opus-4-8"),
                    name: String::from("Claude Opus 4.8"),
                    provider: String::from("anthropic"),
                    connection_id: None,
                    connection_display: None,
                },
            ]
        );
    }

    #[test]
    fn catalog_publication_emits_curated_and_complete_snapshots_with_unknown_active_row() {
        let (tx, mut rx) = mpsc::unbounded_channel();
        let mut provider = provider_test_config();
        provider.model = String::from("unknown-active");
        provider.catalog_models = vec![
            CatalogModelEntry {
                curated: true,
                ..catalog_entry("known-curated", "Known Curated", "anthropic")
            },
            CatalogModelEntry {
                curated: false,
                ..catalog_entry("complete-only", "Complete Only", "anthropic")
            },
        ]
        .into();

        send_native_models(&tx, Some(&provider), None);

        let curated = rx.try_recv();
        let Ok(BackendEvent::Server(ServerEvent::AvailableModelsUpdated { models: curated })) =
            curated
        else {
            unreachable!("curated snapshot is published first");
        };
        let complete = rx.try_recv();
        let Ok(BackendEvent::Server(ServerEvent::DiscoveredModelsUpdated { models: complete })) =
            complete
        else {
            unreachable!("complete snapshot follows the same publication");
        };

        assert_eq!(
            curated
                .iter()
                .map(|model| model.id.as_str())
                .collect::<Vec<_>>(),
            vec!["unknown-active", "known-curated"]
        );
        assert_eq!(
            complete
                .iter()
                .map(|model| model.id.as_str())
                .collect::<Vec<_>>(),
            vec!["unknown-active", "known-curated", "complete-only"]
        );
    }

