    struct ProviderTempRoot {
        path: std::path::PathBuf,
    }

    impl ProviderTempRoot {
        fn path(&self) -> &std::path::Path {
            &self.path
        }
    }

    impl Drop for ProviderTempRoot {
        fn drop(&mut self) {
            let _ = std::fs::remove_dir_all(&self.path);
        }
    }

    fn temp_native_provider_root(label: &str) -> ProviderTempRoot {
        let mut path = std::env::temp_dir();
        path.push(format!(
            "yach-{label}-{}",
            std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)
                .map_or(0, |duration| duration.as_nanos())
        ));
        assert!(std::fs::create_dir_all(&path).is_ok());
        ProviderTempRoot { path }
    }

    #[derive(Default)]
    struct FakeConnectionRuntime {
        list_calls: AtomicU64,
        create_calls: AtomicU64,
        remove_calls: AtomicU64,
        activation_calls: AtomicU64,
        refresh_calls: AtomicU64,
        connections: Vec<ProviderConnection>,
        cached_models: Option<Arc<[CatalogModelEntry]>>,
        list_outcomes: Mutex<VecDeque<oneshot::Receiver<crate::ConnectionListOutcome>>>,
        refresh_outcomes: Mutex<VecDeque<oneshot::Receiver<ModelDiscoveryOutcome>>>,
        remove_outcomes: Mutex<VecDeque<oneshot::Receiver<crate::ConnectionMutationOutcome>>>,
        activation_outcomes: Mutex<VecDeque<oneshot::Receiver<crate::ProviderActivationOutcome>>>,
        remembered_selection: Option<crate::ActiveModelTarget>,
        remembered_targets: Mutex<Vec<crate::ActiveModelTarget>>,
    }

    impl FakeConnectionRuntime {
        fn recorded_remembered_targets(&self) -> Vec<crate::ActiveModelTarget> {
            match self.remembered_targets.lock() {
                Ok(targets) => targets.clone(),
                Err(poisoned) => poisoned.into_inner().clone(),
            }
        }
    }

    impl crate::ProviderConnectionRuntime for FakeConnectionRuntime {
        fn list(&self) -> crate::ConnectionListFuture {
            self.list_calls.fetch_add(1, Ordering::SeqCst);
            let receiver = match self.list_outcomes.lock() {
                Ok(mut outcomes) => outcomes.pop_front(),
                Err(poisoned) => poisoned.into_inner().pop_front(),
            };
            let connections = self.connections.clone();
            Box::pin(async move {
                match receiver {
                    Some(receiver) => {
                        receiver
                            .await
                            .unwrap_or(crate::ConnectionListOutcome::Failed(
                                crate::ConnectionRuntimeFailure::Unavailable,
                            ))
                    }
                    None => crate::ConnectionListOutcome::available(connections),
                }
            })
        }

        fn cached_models(&self) -> Option<Arc<[CatalogModelEntry]>> {
            self.cached_models.clone()
        }

        fn refresh_models(&self, _: Option<crate::ActiveModelTarget>) -> ModelDiscoveryFuture {
            self.refresh_calls.fetch_add(1, Ordering::SeqCst);
            let receiver = match self.refresh_outcomes.lock() {
                Ok(mut outcomes) => outcomes.pop_front(),
                Err(poisoned) => poisoned.into_inner().pop_front(),
            };
            Box::pin(async move {
                match receiver {
                    Some(receiver) => receiver.await.unwrap_or(ModelDiscoveryOutcome::Failed {
                        message: String::from("test refresh sender dropped"),
                    }),
                    None => ModelDiscoveryOutcome::Available(Vec::new()),
                }
            })
        }

        fn create(
            &self,
            _: NewConnectionDraft,
            _: ProviderSecret,
        ) -> crate::ConnectionMutationFuture {
            self.create_calls.fetch_add(1, Ordering::SeqCst);
            Box::pin(async { crate::ConnectionMutationOutcome::Succeeded })
        }

        fn repair(&self, _: ConnectionId, _: ProviderSecret) -> crate::ConnectionMutationFuture {
            Box::pin(async { crate::ConnectionMutationOutcome::Succeeded })
        }

        fn replace(
            &self,
            _: ConnectionId,
            _: Option<String>,
            _: ProviderSecret,
        ) -> crate::ConnectionReplacementFuture {
            Box::pin(async { crate::ConnectionReplacementOutcome::Succeeded { candidate: None } })
        }

        fn rename(&self, _: ConnectionId, _: Option<String>) -> crate::ConnectionMutationFuture {
            Box::pin(async { crate::ConnectionMutationOutcome::Succeeded })
        }

        fn remove(&self, _: ConnectionId) -> crate::ConnectionMutationFuture {
            self.remove_calls.fetch_add(1, Ordering::SeqCst);
            let receiver = match self.remove_outcomes.lock() {
                Ok(mut outcomes) => outcomes.pop_front(),
                Err(poisoned) => poisoned.into_inner().pop_front(),
            };
            Box::pin(async move {
                match receiver {
                    Some(receiver) => {
                        receiver
                            .await
                            .unwrap_or(crate::ConnectionMutationOutcome::Failed(
                                crate::ConnectionRuntimeFailure::Unavailable,
                            ))
                    }
                    None => crate::ConnectionMutationOutcome::Succeeded,
                }
            })
        }

        fn activate(&self, _: ConnectionId, _: String) -> crate::ProviderActivationFuture {
            self.activation_calls.fetch_add(1, Ordering::SeqCst);
            let receiver = match self.activation_outcomes.lock() {
                Ok(mut outcomes) => outcomes.pop_front(),
                Err(poisoned) => poisoned.into_inner().pop_front(),
            };
            Box::pin(async move {
                match receiver {
                    Some(receiver) => {
                        receiver
                            .await
                            .unwrap_or(crate::ProviderActivationOutcome::Failed(
                                crate::ConnectionRuntimeFailure::Unavailable,
                            ))
                    }
                    None => crate::ProviderActivationOutcome::Failed(
                        crate::ConnectionRuntimeFailure::Unavailable,
                    ),
                }
            })
        }

        fn remembered_selection(&self) -> Option<crate::ActiveModelTarget> {
            self.remembered_selection.clone()
        }

        fn remember_selection(&self, target: crate::ActiveModelTarget) {
            match self.remembered_targets.lock() {
                Ok(mut targets) => targets.push(target),
                Err(poisoned) => poisoned.into_inner().push(target),
            }
        }
    }

    #[tokio::test]
    async fn connection_mutation_emits_terminal_for_in_flight_activation() {
        let runtime: Arc<dyn crate::ProviderConnectionRuntime> =
            Arc::new(FakeConnectionRuntime::default());
        let flow = ProviderConnectionFlow::new(None);
        let (backend_tx, mut backend_rx) = mpsc::unbounded_channel();
        let (connection_update_tx, _connection_update_rx) = mpsc::unbounded_channel();
        let (model_refresh_tx, _model_refresh_rx) = mpsc::unbounded_channel();
        let mut model_refresh_generation = 0;
        let mut model_refresh_in_flight = None;
        let mut model_refresh_pending = false;
        let mut activation_generation = 7;
        let mut activation_in_flight = Some(InFlightModelActivation {
            generation: 7,
            target: model_change_target(
                "picked-model",
                Some("connection-a"),
                Some("anthropic"),
                Some(92),
            ),
        });

        apply_connection_flow_effects(
            vec![ConnectionFlowEffect::StartMutation(
                ConnectionMutationOperation::Remove {
                    id: ConnectionId::new_stored(),
                },
            )],
            ConnectionFlowEffectContext {
                runtime: Some(&runtime),
                tx: &backend_tx,
                flow: &flow,
                provider: None,
                connection_updates: &connection_update_tx,
                model_refresh_updates: &model_refresh_tx,
                model_refresh_generation: &mut model_refresh_generation,
                model_refresh_in_flight: &mut model_refresh_in_flight,
                model_refresh_pending: &mut model_refresh_pending,
                activation_generation: &mut activation_generation,
                activation_in_flight: &mut activation_in_flight,
            },
        );

        assert!(activation_in_flight.is_none());
        assert_eq!(activation_generation, 8);
        assert!(matches!(
            backend_rx.recv().await,
            Some(BackendEvent::Server(ServerEvent::StatusUpdated { message }))
                if message == "model change cancelled: connection change started"
        ));
        assert!(matches!(
            backend_rx.recv().await,
            Some(BackendEvent::Server(ServerEvent::ModelChangeFailed(target)))
                if target.model == "picked-model"
                    && target.connection_id.as_deref() == Some("connection-a")
                    && target.provider.as_deref() == Some("anthropic")
                    && target.request_id == Some(92)
        ));
    }

